        var(--surface);
      box-shadow: var(--shadow);
    }

    .hero-card::before,
    .hero-card::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      background: rgba(255, 122, 89, 0.15);
    }

    .hero-card::before {
      width: 180px;
      height: 180px;
      right: -54px;
      top: -48px;
    }

    .hero-card::after {
      width: 120px;
      height: 120px;
      left: -28px;
      bottom: -36px;
      background: rgba(74, 144, 226, 0.12);
    }

