    .stat span {
      color: var(--muted);
      font-size: 0.92rem;
    }

    .faq-list {
      padding: 12px;
    }

    .example {
      overflow: hidden;
      border: 1px solid var(--border);
      border-radius: 24px;
      background: var(--surface);
      transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
