    .question {
      display: flex;
      width: 100%;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      padding: 22px 24px;
      border: 0;
      color: inherit;
      background: transparent;
      font: inherit;
      font-size: 1.05rem;
      font-weight: 800;
      line-height: 1.35;
      text-align: left;
      cursor: pointer;
    }

    .question:hover {
      color: var(--accent-dark);
    }

    .question:focus-visible {
      outline: 4px solid var(--ring);
      outline-offset: -6px;
      border-radius: 22px;
    }

    .icon {
      flex: 0 0 auto;
      display: grid;
      width: 34px;
      height: 34px;
      place-items: center;
      border-radius: 50%;
      color: var(--accent-dark);
      background: #fff2ea;
      transition: transform 180ms ease, background 180ms ease;
    }

    .question[aria-expanded="true"] .icon {
      transform: rotate(45deg);
      background: #ffe4d7;
    }

    .details {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 240ms ease;
